function exactStringArray(
  value: unknown,
  field: string,
  maximum = 20,
): readonly string[] {
  if (
    !Array.isArray(value) ||
    value.length < 1 ||
    value.length > maximum ||
    value.some((entry) => typeof entry !== "string")
