    if (
      typeof input.scope !== "string" ||
      input.scope
        .split(" ")
        .filter(Boolean)
        .some((scope) => !isOAuthScope(scope))
    ) {
      throw new OAuthError(
        "invalid_scope",
        "The client requested an unsupported scope",
      );
    }
  }
  return {
