  if (safe.retryAfterSeconds !== undefined) {
    headers.set("retry-after", String(safe.retryAfterSeconds));
  }
  return new Response(
    JSON.stringify({
      error: safe.code,
      error_description: safe.description,
    }),
    { status: safe.status, headers },
  );
