interface OtpRequestBody {
  readonly email?: unknown;
  readonly code?: unknown;
  readonly purpose?: unknown;
  readonly turnstileToken?: unknown;
}

export interface CreateAuthApplicationInput {
  readonly authfn: AuthFnInstance;
