const OTP_PURPOSES = new Set<AuthFnOtpPurpose>([
  "verify-email",
  "sign-in",
  "sign-up",
  "reset-password",
]);

function requestId(request: Request): string {
  const incoming = request.headers.get("x-request-id")?.trim();
  return incoming?.length ? incoming : `req_${crypto.randomUUID()}`;
}

function failure(
  request: Request,
  status: number,
  code: string,
  message: string,
  retryable = false,
  headers?: HeadersInit,
): Response {
  const id = requestId(request);
  const responseHeaders = new Headers(headers);
  responseHeaders.set("content-type", "application/json");
  responseHeaders.set("cache-control", "private, no-store");
  responseHeaders.set("x-request-id", id);
  return new Response(
    JSON.stringify({
      ok: false,
      error: { code, message, retryable },
      requestId: id,
    }),
    { status, headers: responseHeaders },
  );
}

function success(
  request: Request,
  data: Record<string, unknown>,
  headers?: HeadersInit,
): Response {
  const id = requestId(request);
  const responseHeaders = new Headers(headers);
  responseHeaders.set("content-type", "application/json");
  responseHeaders.set("cache-control", "private, no-store");
  responseHeaders.set("x-request-id", id);
  return new Response(JSON.stringify({ ok: true, data, requestId: id }), {
    status: 200,
    headers: responseHeaders,
  });
}

async function readBody(request: Request): Promise<OtpRequestBody | null> {
  try {
    const body: unknown = await request.json();
    return typeof body === "object" && body !== null ? body : null;
  } catch {
    return null;
  }
}

function normalizeEmail(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const email = value.trim().toLowerCase();
  return email.length <= 254 &&
    !/[\r\n<>]/.test(email) &&
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
