    10	import { runOfficialConformance } from "../mcpfn/testing/dist/index.js";
    11	
    12	const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
    13	const outputRoot = await mkdtemp(path.join(tmpdir(), "mcpfn-conformance-"));
    14	const server = spawn(
    15	  process.execPath,
    16	  [
    17	    path.join(repoRoot, "node_modules/jiti/lib/jiti-cli.mjs"),
    18	    path.join(repoRoot, "mcpfn/examples/conformance-http-server.ts"),
    19	  ],
    20	  { cwd: repoRoot, stdio: ["ignore", "pipe", "pipe"] },
    21	);
    22	let serverStderr = "";
    23	server.stderr.on("data", (chunk) => {
    24	  serverStderr += chunk.toString();
    25	});
    26	
    27	try {
    28	  const url = await new Promise((resolve, reject) => {
    29	    const lines = readline.createInterface({ input: server.stdout });
    30	    const timer = setTimeout(() => {
    31	      reject(new Error(`McpFn conformance server did not start. ${serverStderr}`));
    32	    }, 10_000);
    33	    lines.once("line", (line) => {
    34	      clearTimeout(timer);
    35	      lines.close();
    36	      resolve(line.trim());
    37	    });
    38	    server.once("error", reject);
    39	    server.once("exit", (code) => {
    40	      clearTimeout(timer);
    41	      reject(new Error(`McpFn conformance server exited with ${code}. ${serverStderr}`));
    42	    });
    43	  });
    44	
    45	  const suite = "active";
    46	  const result = await runOfficialConformance({
    47	    url,
    48	    suite,
    49	    outputDir: outputRoot,
    50	    cwd: repoRoot,
    51	    stdio: "pipe",
    52	  });
    53	  if (result.exitCode !== 0) {
    54	    throw new Error(
    55	      `Official MCP conformance failed for the ${suite} suite.\n${result.stdout}\n${result.stderr}`,
    56	    );
    57	  }
    58	  process.stdout.write(`${JSON.stringify({ ok: true, suite })}\n`);
    59	} finally {
    60	  server.kill("SIGTERM");
    61	  await new Promise((resolve) => {
    62	    if (server.exitCode !== null || server.signalCode !== null) resolve();
    63	    else server.once("exit", resolve);
    64	  });
    65	  await rm(outputRoot, { recursive: true, force: true });
    66	}

