     1	# `@mcpfn/auth`
     2	
     3	Web Standard OAuth resource-server support for MCP servers.
     4	
     5	It publishes RFC 9728 protected-resource metadata, validates Bearer tokens through the official SDK's `OAuthTokenVerifier` contract, enforces token expiry, resource indicators, and scopes, and passes trusted `authInfo` into the McpFn HTTP transport. Authorization-code, PKCE, DCR, and token issuance remain the authorization server's responsibility.
     6	
     7	```ts
     8	import { createOAuthResourceServerHandler } from "@mcpfn/auth";
     9	
    10	const mcp = await server.createWebStandardHandler({ enableJsonResponse: true });
    11	const fetch = createOAuthResourceServerHandler(mcp, {
    12	  resource: "https://api.example.com/mcp",
    13	  authorizationServers: ["https://login.example.com"],
    14	  scopesSupported: ["mcp:read"],
    15	  requiredScopes: ["mcp:read"],
    16	  verifier,
    17	});
    18	```
    19	
    20	Enterprise-managed authorization helpers advertise the stable ID-JAG grant profile in authorization-server metadata and build the request metadata used by supporting clients.
resource-server implementation
     1	import type { AuthInfo } from "@modelcontextprotocol/sdk/server/auth/types.js";
     2	import type { OAuthTokenVerifier } from "@modelcontextprotocol/sdk/server/auth/provider.js";
     3	import type { HandleRequestOptions } from "@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js";
     4	
     5	export interface McpFnProtectedResourceMetadata extends Record<string, unknown> {
     6	  resource: string;
     7	  authorization_servers: string[];
     8	  scopes_supported?: string[];
     9	  bearer_methods_supported?: string[];
    10	  resource_name?: string;
    11	  resource_documentation?: string;
    12	}
    13	
    14	export interface McpFnProtectedResourceOptions {
    15	  resource: string | URL;
    16	  authorizationServers: Array<string | URL>;
    17	  scopesSupported?: string[];
    18	  resourceName?: string;
    19	  resourceDocumentation?: string;
    20	  extraMetadata?: Record<string, unknown>;
    21	}
    22	
    23	export interface McpFnOAuthResourceServerOptions
    24	  extends McpFnProtectedResourceOptions {
    25	  verifier: OAuthTokenVerifier;
    26	  requiredScopes?: string[] | ((request: Request) => string[] | Promise<string[]>);
    27	  clock?: () => number;
    28	}
    29	
    30	export type McpFnWebStandardHandler = (
    31	  request: Request,
    32	  options?: HandleRequestOptions,
    33	) => Promise<Response>;
    34	
    35	function normalizeResource(resource: string | URL): URL {
    36	  const url = new URL(resource.toString());
    37	  url.hash = "";
    38	  return url;
    39	}
    40	
    41	function unique(values: Array<string | URL>): string[] {
    42	  return [...new Set(values.map((value) => new URL(value.toString()).toString()))].sort();
    43	}
    44	
    45	export function protectedResourceMetadataUrl(resource: string | URL): URL {
    46	  const normalized = normalizeResource(resource);
    47	  const path = normalized.pathname === "/" ? "" : normalized.pathname;
    48	  return new URL(`/.well-known/oauth-protected-resource${path}`, normalized.origin);
    49	}
    50	
    51	export function createProtectedResourceMetadata(
    52	  options: McpFnProtectedResourceOptions,
    53	): McpFnProtectedResourceMetadata {
    54	  const resource = normalizeResource(options.resource);
    55	  if (!options.authorizationServers.length) {
    56	    throw new Error("At least one OAuth authorization server is required");
    57	  }
    58	  return {
    59	    ...options.extraMetadata,
    60	    resource: resource.toString(),
    61	    authorization_servers: unique(options.authorizationServers),
    62	    ...(options.scopesSupported
    63	      ? { scopes_supported: [...new Set(options.scopesSupported)].sort() }
    64	      : {}),
    65	    bearer_methods_supported: ["header"],
    66	    ...(options.resourceName ? { resource_name: options.resourceName } : {}),
    67	    ...(options.resourceDocumentation
    68	      ? { resource_documentation: new URL(options.resourceDocumentation).toString() }
    69	      : {}),
    70	  };
    71	}
    72	
    73	function json(status: number, body: unknown, headers: HeadersInit = {}): Response {
    74	  return new Response(JSON.stringify(body), {
    75	    status,
    76	    headers: {
    77	      "content-type": "application/json; charset=utf-8",
    78	      "cache-control": "no-store",
    79	      ...Object.fromEntries(new Headers(headers)),
    80	    },
    81	  });
    82	}
    83	
    84	function bearerChallenge(
    85	  metadataUrl: URL,
    86	  details: { error?: string; description?: string; scope?: string } = {},
    87	): string {
    88	  const fields = [`resource_metadata="${metadataUrl.toString()}"`];
    89	  if (details.error) fields.push(`error="${details.error}"`);
    90	  if (details.description) {
    91	    fields.push(`error_description="${details.description.replace(/["\\]/g, "")}"`);
    92	  }
    93	  if (details.scope) fields.push(`scope="${details.scope.replace(/["\\]/g, "")}"`);
    94	  return `Bearer ${fields.join(", ")}`;
    95	}
    96	
    97	function authError(
    98	  status: 401 | 403,
    99	  metadataUrl: URL,
   100	  details: { error: string; description: string; scope?: string },
   101	): Response {
   102	  return json(
   103	    status,
   104	    { error: details.error, error_description: details.description },
   105	    { "www-authenticate": bearerChallenge(metadataUrl, details) },
   106	  );
   107	}
   108	
   109	function bearerToken(request: Request): string | undefined {
   110	  const authorization = request.headers.get("authorization");
   111	  if (!authorization) return undefined;
   112	  const match = /^Bearer\s+([^\s]+)$/i.exec(authorization.trim());
   113	  return match?.[1];
   114	}
   115	
   116	export function createOAuthResourceServerHandler(
   117	  mcpHandler: McpFnWebStandardHandler,
   118	  options: McpFnOAuthResourceServerOptions,
   119	): (request: Request) => Promise<Response> {
   120	  const resource = normalizeResource(options.resource);
   121	  const metadata = createProtectedResourceMetadata(options);
   122	  const metadataUrl = protectedResourceMetadataUrl(resource);
   123	  return async (request: Request): Promise<Response> => {
   124	    const requestUrl = new URL(request.url);
   125	    if (
   126	      request.method === "GET" &&
   127	      requestUrl.origin === metadataUrl.origin &&
   128	      requestUrl.pathname === metadataUrl.pathname
   129	    ) {
   130	      return json(200, metadata, { "cache-control": "public, max-age=300" });
   131	    }
   132	
   133	    const token = bearerToken(request);
   134	    if (!token) {
   135	      return authError(401, metadataUrl, {
   136	        error: "invalid_token",
   137	        description: "A Bearer access token is required",
   138	      });
   139	    }
   140	
   141	    let authInfo: AuthInfo;
   142	    try {
   143	      authInfo = await options.verifier.verifyAccessToken(token);
   144	    } catch {
   145	      return authError(401, metadataUrl, {
   146	        error: "invalid_token",
   147	        description: "The access token is invalid",
   148	      });
   149	    }
   150	    const now = Math.floor((options.clock?.() ?? Date.now()) / 1_000);
   151	    if (authInfo.expiresAt !== undefined && authInfo.expiresAt <= now) {
   152	      return authError(401, metadataUrl, {
   153	        error: "invalid_token",
   154	        description: "The access token has expired",
   155	      });
   156	    }
   157	    if (
   158	      !authInfo.resource ||
   159	      normalizeResource(authInfo.resource).toString() !== resource.toString()
   160	    ) {
   161	      return authError(401, metadataUrl, {
   162	        error: "invalid_token",
   163	        description: "The access token is not bound to this resource",
   164	      });
   165	    }
   166	
   167	    const requiredScopes = typeof options.requiredScopes === "function"
   168	      ? await options.requiredScopes(request)
   169	      : options.requiredScopes ?? [];
   170	    const grantedScopes = new Set(authInfo.scopes);
   171	    const missingScopes = requiredScopes.filter((scope) => !grantedScopes.has(scope));
   172	    if (missingScopes.length) {
   173	      return authError(403, metadataUrl, {
   174	        error: "insufficient_scope",
   175	        description: "The access token lacks required scopes",
   176	        scope: [...new Set(requiredScopes)].sort().join(" "),
   177	      });
   178	    }
   179	    return mcpHandler(request, { authInfo });
   180	  };
   181	}

